head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05930";
scwin.todayDd = "";         // 서버 현재일 (yyyyMMdd) — 원본 cGetToday("yyyymmdd")(클라이언트 날짜)
scwin.jobTitl = "";         // 직책 (03: 담당자, 그 외: 팀장) — 원본 js_jobtitl(pJobTitl)
scwin.depCd = "";           // 부서코드 (ZSYS: 시스템관리자 → 재마감처리 버튼 보임) — 원본 js_dep_cd
scwin.procJob = "";         // 진행 중인 처리명 (확인·완료·실패 메시지 인자) — 원본 procJob
scwin.TAB_PROC = 0;         // [ELW마감처리] 탭 (원본 MaxTab_01 ActiveIndex 1)
scwin.TAB_SEARCH = 1;       // [ELW마감처리내역] 탭 (원본 ActiveIndex 2)
scwin.VIEW_PROC = "N";      // 조회구분 — 마감일이 오늘이고 마감 전이면 N(마감처리 목록), 아니면 S(마감처리내역 목록) (명세 ④ clsViewTpCd)
scwin.JOBTITL_CHRG = "03";  // 직책코드 — 담당자
scwin.DEP_CD_SYS = "ZSYS";  // 부서코드 — 시스템관리자
scwin.CORR_OK = "O";        // 송수신데이터 일치 (원본 SNDRCV_DATA_CORR_YN "O")
// 내역 탭에서만 보이는 위쪽 칸 — 송수신 일치여부·담당자·팀장 (원본 MaxTab_01 OnSelChanged 의 showObj 대상)
scwin.SEARCH_ONLY_IDS = ["lb_NEW_SNDRCV_DATA_CORR_YN", "txb_NEW_SNDRCV_DATA_CORR_YN", "lb_ADD_SNDRCV_DATA_CORR_YN", "txb_ADD_SNDRCV_DATA_CORR_YN",
    "lb_APPROV_EMP_NM", "txb_APPROV_EMP_NM", "lb_APPROV_TM", "txb_APPROV_TM",
    "lb_TEAMLEADR_EMP_NM", "txb_TEAMLEADR_EMP_NM", "lb_TEAMLEADR_TM", "txb_TEAMLEADR_TM"];

// 원본 : /lstproc/ULDSTF05930.gfm (ELW 마감처리 / ELW마감처리내역, 메인 화면 — 탭 2개)
/*
 * 화면 동작
 *  - 마감일(기본 오늘)로 조회하면 상장일(다음 영업일)·마감정보와 신규·추가상장 목록이 한 번에 온다(명세 ④).
 *    마감일이 오늘이고 마감 전이면 마감처리 목록(clsViewTpCd N), 그 밖이면 마감처리내역 목록(S)을 서버가 정한다.
 *  - [ELW마감처리] 탭: [마감처리] = 명세 ③ 담당자승인(마감처리 + 담당자 확인을 한 트랜잭션으로). 시스템관리자(ZSYS)는 [재마감처리](명세 ①).
 *  - [ELW마감처리내역] 탭: 송수신 일치여부·담당자·팀장 칸을 보이고, 팀장은 [팀장승인](명세 ②)을 한다.
 *  - 두 탭의 그리드는 같은 목록(dlt_listNewListingList·dlt_listAddListingList)을 보인다 — 내역 탭 그리드에 일치여부·LP보유수량 열이 더 있다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05930/ULDSTF05930.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 세션 정보 → init 바인딩 → 버튼 초기 상태 → 마감일 = 오늘, [ELW마감처리] 탭 칸 상태 → 조회. (원본 gform onload — §3)
 * 탭 본문은 alwaysDraw="true" 라 처음부터 그려져 있어 탭 안 버튼도 여기서 제어한다(규칙 45 예외, 선례 ULDSTF08200·70016).
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 세션·서버 날짜 — 원본 js_jobtitl·js_dep_cd 전역, cGetToday("yyyymmdd")
    scwin.jobTitl = $c.session.getUserInfo("jobtitl") ?? "";
    scwin.depCd = $c.session.getUserInfo("depCd") ?? "";
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 2) init 바인딩 (전환 규칙 22·37) — 마감일 단일 달력, 조회 영역 Enter 키
    $c.date.checkCalendarFormat(edt_TASK_DD, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 버튼 초기 상태 — 재마감처리는 시스템관리자만 보이고, 마감처리·팀장승인은 조회 뒤 마감정보로 정한다(그 전까지 잠금)
    scwin.applyReTrSendButton();
    scwin.lockButtons();

    // 4) 마감일 = 오늘, [ELW마감처리] 탭은 내역 전용 칸을 숨긴다 (원본 setObjectValue(edt_TASK_DD, 오늘) + ActiveIndex = 1)
    dma_search.set("taskDd", scwin.todayDd);
    scwin.applyTabMode(scwin.TAB_PROC);

    // 5) 조회 (원본 fn_list_sync + fn_btnDisable)
    await scwin.searchList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_01_onchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 변경 — 탭에 맞춰 내역 전용 칸(송수신 일치여부·담당자·팀장)을 보이거나 숨기고 다시 조회한다. (원본 MaxTab_01 OnSelChanged — §4, §6.1)
 * @param {String} tabId 선택한 탭 id
 * @param {Number} index 선택한 탭 순번
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.applyTabMode(Number(MaxTab_01.getSelectedTabIndex()));
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.MaxTab_01_onchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함) — 마감일 기준으로 다시 조회한다. (원본 btn_Search onclick → fn_list_sync + fn_btnDisable — §5.1)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ReTrSend_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 버튼 클릭 (시스템관리자만 보임) — 처리는 scwin.reTrSend. (원본 btn_ReTrSend onclick → fn_re_trsend — §6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ReTrSend_onclick = async function (e) {
    try {
        await scwin.reTrSend();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_ReTrSend_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_TrSend_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감처리 버튼 클릭 — 처리는 scwin.trSend(담당자승인 = 마감처리 + 담당자 확인). (원본 btn_TrSend onclick → fn_trsend — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_TrSend_onclick = async function (e) {
    try {
        await scwin.trSend();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_TrSend_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_rcvTeamleadr_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인 버튼 클릭 — 처리는 scwin.rcvTeamleadr. (원본 btn_rcvTeamleadr onclick → fn_rcvTeamleadr — §6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_rcvTeamleadr_onclick = async function (e) {
    try {
        await scwin.rcvTeamleadr();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_rcvTeamleadr_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ProcExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [ELW마감처리] 엑셀저장 버튼 클릭 — 선택한 탭의 신규·추가상장 그리드를 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ProcExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_ProcExcel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_SearchExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [ELW마감처리내역] 엑셀저장 버튼 클릭 — 선택한 탭의 신규·추가상장 그리드를 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_SearchExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.btn_SearchExcel_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_New_Search_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감처리내역 신규상장 그리드 더블클릭 — 한글종목약명 칸이면 그 종목의 송수신 일치여부 확인 팝업을 연다. (원본 grd_New_Search OnDblClick → fn_sndRcvCorrYn — §6.6)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_New_Search_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId !== "isuKorAbbrv") return;
        await scwin.openCorrYn(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.grd_New_Search_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 마감일 기준 상장일·마감정보·신규/추가상장 목록 → 건수 → 송수신 일치여부 → 버튼 상태.
 * (원본 dts_Get_ListDD·dts_Item·dts_New_Proc/dts_Add_Proc(또는 dts_New_Search/dts_Add_Search) Reset + OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.searchList = async function () {
    // 원본 Reset 은 다시 읽기 전에 비운다 — 실패해도 앞 조회 결과로 마감하지 않게 한다.
    scwin.clearHeader();
    dlt_listNewListingList.removeAll();
    dlt_listAddListingList.removeAll();
    scwin.fillCounts();

    // 명세 target 의 dma_listClsProcsInfo=body.clsProcsInfo 는 뺐다 — 마감 전이면 clsProcsInfo 가 null 일 수 있고, 공통 바인딩은 null 을 그대로 setJSON 에 넘긴다.
    // 객체가 올 때만 scwin.applyClsProcsInfo 가 적재한다(선례 ULDSTF70016 finalLog — §5 「명세 ↔ AS-IS 차이」, §10 #3).
    const sbmOptions = {
        id : "sbm_list",
        method : "get",
        action : "/api/listing/lstproc/elw/cls-procs/select-list",
        target : "dma_list=body, dlt_listNewListingList=body.newListingList, dlt_listAddListingList=body.addListingList",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : dma_search.get("taskDd") });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        // 마감정보와 목록이 맞지 않는 상태로 처리하지 않도록 잠근다(§8 #5).
        scwin.lockButtons();
        return;
    }

    scwin.applyClsProcsInfo(result.responseJSON.body?.clsProcsInfo);
    scwin.fillCounts();
    dma_search.set("newSndrcvDataCorrYn", scwin.calcCorrYn(dlt_listNewListingList));
    dma_search.set("addSndrcvDataCorrYn", scwin.calcCorrYn(dlt_listAddListingList));
    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.searchUnprocessedIsu
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자승인(마감처리) 전 미처리(신청완료·접수) 종목 조회. 결과가 있어도 승인은 할 수 있고, 진행 여부를 묻는 데 쓴다. (원본 fn_UnRcvIsuCheck 의 dts_UnRcvIsuChk — §5.5)
 * @returns {Promise<Array|null>} 미처리 종목 목록, 조회 실패·건너뜀이면 null
 * @hidden N
 */
scwin.searchUnprocessedIsu = async function () {
    dlt_listUnprocessedIsu.removeAll();

    const sbmOptions = {
        id : "sbm_listUnprocessedIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/cls-procs/select-list-unprocessed-isu",
        target : "dlt_listUnprocessedIsu=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : dma_search.get("taskDd"), listDd : dma_list.get("listDd") });
    if (result?.skipped || !result.responseJSON?.success) return null;
    return dlt_listUnprocessedIsu.getAllJSON();
};

/**
 * @method
 * @name scwin.postClose
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감 처리 전송(담당자승인·팀장승인·재마감처리 공통). 요청 dataMap 에 마감일·상장일을 넣어 보내고, 성공하면 완료 안내 후 다시 조회한다.
 * 실패(통신 실패 또는 처리결과 F)면 서버 메시지(없으면 MSG-A002)를 안내한다. 옵션 객체는 부르는 쪽이 호출마다 새로 만든다(공통 함수가 옵션을 고친다 — 선례 ULDSTF09350).
 * (원본 trs_Save Post + OnSuccess·OnFail — §5.2~§5.4)
 * @param {Object} sbmOptions executeDynamic 옵션 (id·method·action·ref·target·mediatype)
 * @param {Object} reqMap 요청 dataMap (명세 dma_removeClsProcs·dma_registerTeamleadrApprov·dma_registerApprov)
 * @param {Object} resMap 응답 dataMap (명세 …Result)
 * @returns
 * @hidden N
 */
scwin.postClose = async function (sbmOptions, reqMap, resMap) {
    // 명세 요청은 세 API 모두 { taskDd, listDd } — 원본이 dts_Item 에 넣던 사번(CHRG_EMP_NO·APPROV_EMP_NO·APPROV_TEAMLEADR_EMP_NO)·CLS_TYPE·APPROV_TYPE 은 없다(서버 세션, §10 #4).
    reqMap.set("taskDd", dma_search.get("taskDd"));
    reqMap.set("listDd", dma_list.get("listDd"));
    resMap.setEmptyValue();

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀 (원본 연속 클릭 — §8 #6)

    if (!result.responseJSON?.success || resMap.get("result") === "F") {
        const msg = resMap.get("resultMessage");
        await $c.win.alert($c.util.isEmpty(msg) ? $c.stf.getMessageParam("MSG-A002", scwin.procJob) : msg);
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    await scwin.searchList();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.applyTabMode
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭에 맞춰 내역 전용 칸(송수신 일치여부·담당자·팀장)을 [ELW마감처리내역]에서만 보인다. (원본 MaxTab_01 OnSelChanged 의 showObj — §6.1)
 * @param {Number} index 탭 순번 (scwin.TAB_PROC | scwin.TAB_SEARCH)
 * @returns
 * @hidden N
 */
scwin.applyTabMode = function (index) {
    const visible = (index === scwin.TAB_SEARCH);
    scwin.SEARCH_ONLY_IDS.forEach(id => {
        const comp = $p.getComponentById(id);
        if (!comp) return;
        if (visible) comp.show("");
        else comp.hide();
    });
};

/**
 * @method
 * @name scwin.clearHeader
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 전 상장일·마감정보·송수신 일치여부(위쪽 칸)를 비운다. 원본은 dts_Get_ListDD·dts_Item 을 매번 다시 읽었다(Reset). (§5.1)
 * @returns
 * @hidden N
 */
scwin.clearHeader = function () {
    dma_list.setEmptyValue();
    dma_listClsProcsInfo.setEmptyValue();
    dma_search.set("newSndrcvDataCorrYn", "");
    dma_search.set("addSndrcvDataCorrYn", "");
};

/**
 * @method
 * @name scwin.applyClsProcsInfo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 응답의 마감정보를 위쪽 칸에 넣는다. 마감 전이면 비어(null) 올 수 있어 객체일 때만 적재한다. (원본 bnd_Item — §5.1)
 * @param {Object} info 마감정보 (명세 body.clsProcsInfo)
 * @returns
 * @hidden N
 */
scwin.applyClsProcsInfo = function (info) {
    if (info && typeof info === "object") {
        dma_listClsProcsInfo.setJSON(info);
    }
};

/**
 * @method
 * @name scwin.fillCounts
 * @author Inswave
 * @date 2026. 10. 30
 * @description 두 탭의 신규·추가상장 건수를 목록 건수로 채운다(두 탭이 같은 목록을 보인다). (원본 dts_*_OnLoadCompleted 의 "총 n 건" — §5.1)
 * @returns
 * @hidden N
 */
scwin.fillCounts = function () {
    const newCnt = dlt_listNewListingList.getRowCount();
    const addCnt = dlt_listAddListingList.getRowCount();
    $c.stf.fillGridHeaderTotalCnt(newCnt, edt_New_Proc_TotalCnt);
    $c.stf.fillGridHeaderTotalCnt(newCnt, edt_New_Search_TotalCnt);
    $c.stf.fillGridHeaderTotalCnt(addCnt, edt_Add_Proc_TotalCnt);
    $c.stf.fillGridHeaderTotalCnt(addCnt, edt_Add_Search_TotalCnt);
};

/**
 * @method
 * @name scwin.calcCorrYn
 * @author Inswave
 * @date 2026. 10. 30
 * @description 송수신 일치여부 — 파일수신시각이 있을 때만 판정해 모든 행이 일치(O)면 O, 하나라도 아니면 X. 수신 전이거나 행이 없으면 「-」. (원본 fn_setSndRcvCorrYn — §6.2)
 * @param {Object} dataList 판정할 목록 (dlt_listNewListingList | dlt_listAddListingList)
 * @returns {String} O | X | -
 * @hidden N
 */
scwin.calcCorrYn = function (dataList) {
    if ($c.util.isEmpty(dma_listClsProcsInfo.get("rcvTm"))) return "-";

    const rows = dataList.getAllJSON();
    if (rows.length === 0) return "-";
    return rows.every(r => r.sndrcvDataCorrYn === scwin.CORR_OK) ? "O" : "X";
};

/**
 * @method
 * @name scwin.lockButtons
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감처리·팀장승인 버튼을 잠근다 — 조회 전·조회 실패 시. (§6.8)
 * @returns
 * @hidden N
 */
scwin.lockButtons = function () {
    btn_TrSend.setDisabled(true);
    btn_rcvTeamleadr.setDisabled(true);
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 버튼 활성. (원본 fn_setButton + fn_btnDisable — §6.8)
 *  [마감처리]: 마감처리 목록(조회구분 N)이고 마감처리시각이 없을 때만.
 *  [팀장승인]: 팀장(직책이 담당자 03 이 아님)이고, 담당자 확인은 됐고 팀장 확인은 안 됐을 때만.
 *  재마감처리 버튼도 다시 정한다.
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const isProcView = (dma_list.get("clsViewTpCd") === scwin.VIEW_PROC);
    const isClosed = !$c.util.isEmpty(dma_listClsProcsInfo.get("bzClsTm"));
    btn_TrSend.setDisabled(!(isProcView && !isClosed));

    const isChrg = (scwin.jobTitl === scwin.JOBTITL_CHRG);
    const isReviewed = !$c.util.isEmpty(dma_listClsProcsInfo.get("approvEmpNm"));
    const isLeadDone = !$c.util.isEmpty(dma_listClsProcsInfo.get("approvTeamleadrEmpNm"));
    btn_rcvTeamleadr.setDisabled(isChrg || !isReviewed || isLeadDone);

    scwin.applyReTrSendButton();
};

/**
 * @method
 * @name scwin.applyReTrSendButton
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 버튼 — 시스템관리자(ZSYS)만 보이고 활성, 그 밖에는 숨김. (원본 gform onload·fn_setButton 의 showObj(btn_ReTrSend) — §6.8)
 * @returns
 * @hidden N
 */
scwin.applyReTrSendButton = function () {
    if (scwin.depCd === scwin.DEP_CD_SYS) {
        btn_ReTrSend.setDisabled(false);
        btn_ReTrSend.show("");
    } else {
        btn_ReTrSend.hide();
    }
};

/**
 * @method
 * @name scwin.checkProcDt
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감 처리 전 확인 — 마감일이 오늘인지, 신규상장 목록에 발행회사명(시장참가자번호)이 없는 종목·LP보유량이 0 이하인 종목이 없는지. (원본 fn_checkProcDt — §6.2)
 * @param {String} jobNm 처리명 (안내 문구용)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkProcDt = async function (jobNm) {
    if (dma_search.get("taskDd") !== scwin.todayDd) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + jobNm + "'를 할수 있습니다.");
        return false;
    }

    const rows = dlt_listNewListingList.getAllJSON();
    if (rows.some(r => $c.util.isEmpty(r.elwIsuMktpartcNm))) {
        await $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
        return false;
    }
    if (rows.some(r => Number(r.isuShrs) <= 0)) {
        await $c.win.alert("LP보유량이 '0'인 종목이 있습니다. 확인하여주십시오.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.trSend
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감처리 = 명세 ③ 담당자승인(마감처리와 담당자 확인을 한 트랜잭션으로). 마감일·목록 확인 → 상장일 확인 → 미처리 종목이 있으면 목록을 보여 주고 묻고, 없으면 일반 확인 → 전송.
 * 원본의 코드 삭제종목 검사(fn_isuDelCheck)는 대응 API 가 없고 명세상 서버가 막는다(§5 차이). (원본 fn_trsend + fn_rcvApprove — §6.3, §5.4)
 * @returns
 * @hidden N
 */
scwin.trSend = async function () {
    scwin.procJob = "마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    if ($c.util.isEmpty(dma_list.get("listDd"))) {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }

    const unprocessed = await scwin.searchUnprocessedIsu();
    if (unprocessed === null) return;     // 조회 실패 — 안내는 공통 함수가 했다

    let msg = $c.stf.getMessageParam("MSG-A006", scwin.procJob);
    if (unprocessed.length > 0) {
        msg = "미처리 종목이 있습니다" + unprocessed.map(r => "\n - 종목명 : " + r.isuKorAbbrv + " [사유] " + r.listProcsStatNm).join("")
            + "\n\n 마감처리 하시겠습니까?";
    }
    if (!await $c.win.confirm(msg)) return;

    const sbmOptions = {
        id : "sbm_registerApprov",
        method : "post",
        action : "/api/listing/lstproc/elw/cls-procs/register-approv",
        ref : "dma_registerApprov",
        target : "dma_registerApprovResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, dma_registerApprov, dma_registerApprovResult);
};

/**
 * @method
 * @name scwin.reTrSend
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 — 당일 마감기록(송신데이터·마감로그·승인기록)을 지운다. 이후 다시 마감처리해야 한다. (원본 fn_re_trsend — §6.4, §5.2)
 * @returns
 * @hidden N
 */
scwin.reTrSend = async function () {
    scwin.procJob = "재마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    const msg = " 재마감처리를 선택하셨습니다. \n 재마감처리는 이전 마감처리기록을 삭제하므로 \n 재마감처리후 다시 마감처리를 하셔아 됩니다. \n \n 재마감처리 하시겠습니까?";
    if (!await $c.win.confirm(msg)) return;

    const sbmOptions = {
        id : "sbm_removeClsProcs",
        method : "post",
        action : "/api/listing/lstproc/elw/cls-procs/remove-cls-procs",
        ref : "dma_removeClsProcs",
        target : "dma_removeClsProcsResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, dma_removeClsProcs, dma_removeClsProcsResult);
};

/**
 * @method
 * @name scwin.rcvTeamleadr
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인 — 담당자 확인 뒤, 아직 팀장 확인 전일 때만. 원본도 마감일 확인을 하지 않는다. (원본 fn_rcvTeamleadr — §6.5, §5.3)
 * @returns
 * @hidden N
 */
scwin.rcvTeamleadr = async function () {
    scwin.procJob = "팀장확인";

    if ($c.util.isEmpty(dma_listClsProcsInfo.get("approvEmpNm"))) {
        await $c.win.alert("[담당자]가 확인하지 않았습니다. 담당자 확인 후 [팀장] 확인 해주십시오.");
        return;
    }
    if (!$c.util.isEmpty(dma_listClsProcsInfo.get("approvTeamleadrEmpNm"))) {
        await $c.win.alert("이미 [팀장확인] 처리되었습니다.");
        return;
    }
    if (!await $c.win.confirm($c.stf.getMessageParam("MSG-A006", scwin.procJob))) return;

    const sbmOptions = {
        id : "sbm_registerTeamleadrApprov",
        method : "post",
        action : "/api/listing/lstproc/elw/cls-procs/register-teamleadr-approv",
        ref : "dma_registerTeamleadrApprov",
        target : "dma_registerTeamleadrApprovResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, dma_registerTeamleadrApprov, dma_registerTeamleadrApprovResult);
};

/**
 * @method
 * @name scwin.openCorrYn
 * @author Inswave
 * @date 2026. 10. 30
 * @description 송수신 일치여부 확인 팝업(ULDSTF05903_RV)을 그 종목의 마감일·종목코드로 연다. 반환은 없다.
 * 원본은 이 화면에서 일치여부 상세(dts_CorrYn, listGeneral)를 읽은 뒤 팝업이 부모 데이터셋을 참조했다 — 대응 API 가 없어 팝업이 data 로 받아 스스로 조회하는 계약을 제안한다. (원본 fn_sndRcvCorrYn — §6.6)
 * @param {Number} rowIndex 더블클릭한 행
 * @returns
 * @hidden N
 */
scwin.openCorrYn = async function (rowIndex) {
    const options = {
        id : "ULDSTF05903_RV",
        popupName : "ELW 일치여부확인",
        width : 665,
        height : 800,
        type : "pageFramePopup"
    };
    const data = {
        taskDd : dma_search.get("taskDd"),
        isuCd : dlt_listNewListingList.getCellData(rowIndex, "isuCd")
    };

    // TODO: ULDSTF05903_RV 는 미전환 — 경로·data 키는 제안이고 일치여부 상세 조회 API 가 명세에 없다 (§10 #6)
    await $c.win.openPopup("/ui/lst/lstproc/ULDSTF05903_RV.xml", options, data);
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 선택한 탭의 신규·추가상장 그리드를 각각 내려받는다(원본도 두 파일). 행이 있는 그리드만 내려받고, 둘 다 비면 공통 함수의 0건 안내를 한 번만 띄운다.
 * 파일명은 {menuId}_{원본 이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42). (원본 fn_ExcelDown — §6.7)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    const prefix = $c.win.getProgramId() + "_";
    const suffix = "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx";
    const isSearch = (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_SEARCH);
    const grdNew = isSearch ? grd_New_Search : grd_New_Proc;
    const grdAdd = isSearch ? grd_Add_Search : grd_Add_Proc;
    const hasNew = dlt_listNewListingList.getRowCount() > 0;
    const hasAdd = dlt_listAddListingList.getRowCount() > 0;

    if (hasNew || !hasAdd) {
        $c.data.downloadGridViewExcel(grdNew, { fileName : prefix + "신규상장 마감처리목록" + suffix });
    }
    if (hasAdd) {
        $c.data.downloadGridViewExcel(grdAdd, { fileName : prefix + "추가상장 송신목록" + suffix });
    }
};

/**
 * @method
 * @name scwin.fmtCorrYn
 * @author Inswave
 * @date 2026. 10. 30
 * @description 일치여부 열 — 글자색을 blue 로 표시한다. 값은 그대로. (원본 SNDRCV_DATA_CORR_YN color blue — 규칙 40·43)
 * @param {String} data 셀 값
 * @param {String} formattedData 형식 적용 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} colIndex 열 인덱스
 * @returns {String} 표시 값
 * @hidden N
 */
scwin.fmtCorrYn = function (data, formattedData, rowIndex, colIndex) {
    this.setCellClass(rowIndex, colIndex, "blue");
    return formattedData;
};

/**
 * @method
 * @name scwin.fmtDblClickCell
 * @author Inswave
 * @date 2026. 10. 30
 * @description 한글종목약명 열(마감처리내역) — 더블클릭으로 일치여부 확인 팝업을 여는 칸이라 배경을 bg_orange 로 표시한다. (원본 bgcolor #FFFF99·cursor hand — 규칙 40·43, 선례 ULDSTF25205)
 * @param {String} data 셀 값
 * @param {String} formattedData 형식 적용 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} colIndex 열 인덱스
 * @returns {String} 표시 값
 * @hidden N
 */
scwin.fmtDblClickCell = function (data, formattedData, rowIndex, colIndex) {
    this.setCellClass(rowIndex, colIndex, "bg_orange");
    return formattedData;
};
